'use strict';
window.Learning=(()=>{
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const data=()=>profile().learning,words=LEARN.cards,sentences=LEARN.sentences;
 const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
 const later=(day,n)=>{const d=new Date(day+'T12:00:00');d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
 const find=id=>[...words,...sentences].find(c=>c.id===id),title=c=>c.en||c.parts.join(' ');
 const art=c=>`<img class="learn-art" src="assets/forces/${esc(c.art)}.svg" alt="">`;
 let panel='plan',filter='All',favOnly=false,activeId='',activeLab='greenhouse';
 const dialog=document.createElement('dialog');dialog.id='learnDialog';dialog.className='final-dialog';document.body.append(dialog);
 dialog.addEventListener('close',()=>{ForcesLab.stop();stopAudio();});
 $('#journalView').insertAdjacentHTML('afterend','<section id="learnView" hidden></section>');
 $('.tabs').insertAdjacentHTML('beforeend','<button data-tab="learn"><span>✧ Grow</span><small>成长计划</small></button>');
 $('[data-tab="learn"]').onclick=()=>open('plan');
 const tabs=[['plan','My Research Plan','我的复习计划'],['sentences','Sentence Lab','句子实验室'],['bench','Working Base','自由实验基地'],['family','Family Missions','亲子实地任务'],['portfolio','My Portfolio','科学成长档案']];
 function weakness(ch,domain){const r=profile().final.attempts.at(-1);if(!r)return {wrong:0,help:0};const qs=FINAL.forms[r.form];let wrong=0,help=0;qs.forEach((q,i)=>{if(q.chapter!==ch||q.domain!==domain)return;const a=r.answers[i];if(!FinalChallenge.correct(q,a))wrong++;else if(Object.values(a.help||{}).some(Boolean))help++;});return {wrong,help};}
 function reason(id){const c=find(id),s=data().stats[id],w=weakness(c.chapter,id[0]==='s'?'english':'science');if(s&&s.due<=today())return 'Due for a revisit · 到期再练';if(s&&s.due>today())return 'Optional extra practice · 尚未到期，可选巩固';if(w.wrong)return 'Practice after your final challenge · 根据考核回练';if(w.help)return 'Consolidate with less help if ready · 试着减少辅助再巩固';return 'Connect and remember · 联系与巩固';}
 function plan(){
  const d=data(),date=today(),assessment=profile().final.attempts.at(-1)?.finished||'';if(d.day?.date===date&&d.day.assessment===assessment)return d.day;
  const completed=[profile().completed,...['animals','earth','fossils','resources','motion','forces'].map(k=>profile()[k].completed)];
  const allowed=c=>profile().final.attempts.length||completed[c.chapter-1].length||c.chapter===1;
  const priority=c=>{const s=d.stats[c.id],w=weakness(c.chapter,c.id[0]==='s'?'english':'science');return (s&&s.due<=date?100:0)+(s&&s.due>date?-1000:0)+w.wrong*20+w.help*3+(!s?10:0);};
  const rank=list=>list.filter(allowed).sort((a,b)=>priority(b)-priority(a)||(data().stats[a.id]?.last||'').localeCompare(data().stats[b.id]?.last||'')||a.id.localeCompare(b.id,undefined,{numeric:true}));
  const rs=rank(words),ss=rank(sentences),kept=d.day?.date===date?[...d.day.done]:[],ids=[...kept];
  for(const c of rs)if(ids.length<3&&ids.filter(id=>id[0]==='r').length<2&&!ids.includes(c.id))ids.push(c.id);
  for(const c of ss)if(ids.length<3&&!ids.includes(c.id))ids.push(c.id);
  d.day={date,assessment,ids,done:kept};save();return d.day;
 }
 function complete(id,clean,help,stage,variant){
  const d=data(),date=today(),old=d.stats[id];
  if(old?.last!==date){const streak=clean&&!help?Math.min(4,(old?.streak||0)+1):0;d.stats[id]={streak,last:date,due:later(date,[1,1,3,7,14][streak]),runs:(old?.runs||0)+1,first:old?old.first:clean,lastOk:clean,variant:1-variant};}
  else if(!clean||help){old.streak=0;old.due=later(date,1);old.lastOk=old.lastOk&&clean;}
  d.history.push({id,date,ok:clean,help,stage});d.history=d.history.slice(-100);
  const day=plan();if(day.ids.includes(id)&&!day.done.includes(id))day.done.push(id);
  delete d.drafts[id];save();render();
 }
 function star(id){const a=data().favorites;data().favorites=a.includes(id)?a.filter(x=>x!==id):[...a,id];save();}
 function starButton(id){return `<button class="text-button" data-favorite="${id}" aria-pressed="${data().favorites.includes(id)}">${data().favorites.includes(id)?'★ Saved · 已收藏':'☆ Save · 收藏'}</button>`;}
 function bindStars(host,redraw){host.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>{star(b.dataset.favorite);redraw();});}
 function render(){
  const day=plan();
  $('#learnView').innerHTML=`<section class="learn-hero"><div><p class="eyebrow">A LITTLE DEEPER, EACH DAY</p><h2>Keep your curiosity growing.<small>把通关变成真正会用</small></h2><p>Revisit an idea. Try a new example. Tell your story.<small>复习一个概念，尝试新的情境，讲述自己的发现。</small></p></div><img src="assets/golden-frog.webp" alt="Golden Frog"></section><nav class="learn-tabs" aria-label="Learning activities">${tabs.map(([id,en,zh])=>`<button data-learn-tab="${id}" class="${panel===id?'selected':''}" aria-pressed="${panel===id}">${en}<small>${zh}</small></button>`).join('')}</nav><div id="learnPanel">${panel==='plan'?planHTML(day):panel==='sentences'?sentencesHTML():panel==='bench'?benchHTML():panel==='family'?familyHTML():portfolioOverview()}</div>`;
  $$('[data-learn-tab]').forEach(b=>b.onclick=()=>{panel=b.dataset.learnTab;render();});bindPanel();
  for(const place of ['baseView','journalView']){
   $$('#'+place+' .learning-link').forEach(n=>n.remove());
   $('#'+place).insertAdjacentHTML('afterbegin',`<section class="learning-link"><div><p class="eyebrow">YOUR NEXT SMALL DISCOVERY</p><h3>${place==='baseView'?'A base you can work in':'Keep your discoveries together'}<small>${place==='baseView'?'自由实验、亲子任务与每日复习':'词句收藏、成长记录与可打印研究册'}</small></h3><p>Today · 今日 ${day.done.length}/3</p></div><button class="primary" data-grow="${place==='baseView'?'bench':'portfolio'}">${place==='baseView'?'Enter working base':'Open my portfolio'}<small>${place==='baseView'?'进入实验基地':'打开成长档案'}</small> ↗</button><button class="secondary" data-grow="plan">My daily plan<small>今日复习</small></button></section>`);
  }
  $$('[data-grow]').forEach(b=>b.onclick=()=>open(b.dataset.grow));
 }
 function open(which='plan'){panel=which;switchTab('learn');render();$('#learnView').scrollIntoView({block:'start'});}
 function planHTML(day){return `<div class="learn-heading"><h3>Three small discoveries<small>今日3项 · 约8–12分钟，可分次完成</small></h3><span>${day.date} · ${day.done.length}/3</span></div><p class="learn-muted">Choose any order. No streak penalty for taking a day off.<small>顺序自选；休息一天不会扣分。这里的练习不重复刷研究积分。</small></p><div class="learn-grid">${day.ids.map((id,i)=>{const c=find(id);return `<article class="learn-card">${art(c)}<p class="eyebrow">${i+1} · ${id[0]==='s'?'ENGLISH':'SCIENCE'} · CH${c.chapter}</p><h3>${esc(title(c))}<small>${esc(c.zh)}</small></h3><p>${reason(id)}</p><button class="primary" data-study="${id}">${day.done.includes(id)?'✓ Revisit':'Begin'}<small>${day.done.includes(id)?'今日已完成，可重温':'开始这项练习'}</small></button></article>`}).join('')}</div>${day.done.length===3?'<div class="learn-celebrate">✓ Today’s plan is complete.<small>今日计划已完成。可以休息，也可以去实验基地把知识用起来。</small><button class="secondary" data-panel="bench">Try an experiment · 去试验</button></div>':''}<details class="learn-note"><summary>How your plan works · 复习怎样安排</summary><p>Due items come first, then chapters that need practice after the final challenge. Help use is a consolidation cue, not a wrong answer. Independent first-attempt successes are revisited after 1, 3, 7, then 14 days. Errors or clues schedule an earlier revisit.<small>优先到期项目，再参考考核中需要回练的章节；使用辅助只用于安排巩固。首次独立答对按1、3、7、14天安排，出错或查看线索则较早复习。每天最多推进一次间隔；本机日期决定今日计划。</small></p></details><h3>Review library<small>14个概念 · 每个有两种情境</small></h3><div class="learn-grid compact">${words.map(c=>`<article class="learn-card"><h4>${esc(c.en)}<small>${esc(c.zh)} · CH${c.chapter}</small></h4><button class="secondary" data-study="${c.id}">Practise · 练习</button>${starButton(c.id)}</article>`).join('')}</div>`;}
 function sentencesHTML(){const items=sentences.filter(c=>(filter==='All'||c.category===filter)&&(!favOnly||data().favorites.includes(c.id)));return `<div class="learn-heading"><h3>Science Sentence Lab<small>先听懂 → 拼句 → 换情境使用</small></h3></div><div class="learn-filters">${['All','Describe','Compare','Explain','Predict'].map((f,i)=>`<button class="secondary ${f===filter?'selected':''}" data-filter="${f}">${f}<small>${['全部','描述','比较','解释','预测'][i]}</small></button>`).join('')}<button class="secondary ${favOnly?'selected':''}" id="learnFavorites">★ Favorites<small>${favOnly?'仅显示收藏':'查看收藏句子'}</small></button></div><div class="learn-grid">${items.map(c=>`<article class="learn-card">${art(c)}<p class="eyebrow">CH${c.chapter} · ${c.category}</p><h3>${esc(c.parts.join(' '))}<small>${esc(c.zh)}</small></h3><p>${data().levels[c.id]||0}/3 stages complete · 阶段完成</p><button class="primary" data-study="${c.id}">Practise this sentence<small>练习这句话</small></button>${starButton(c.id)}</article>`).join('')||'<p>No saved sentences in this category yet. <small>此分类还没有收藏，可关闭筛选并点星号。</small></p>'}</div>`;}
 function familyHTML(){return `<h3>Family Field Missions<small>把观察带进生活 · 不强制上传照片或录音</small></h3><div class="learn-grid">${LEARN.family.map(f=>`<article class="learn-card">${art(f)}<h3>${esc(f.en)}<small>${esc(f.zh)}</small></h3><p>${esc(f.enprompt)}<small>${esc(f.zhprompt)}</small></p><button class="primary" data-family="${f.id}">${data().family[f.id]?.done?'✓ Open field note':'Begin observation'}<small>${data().family[f.id]?.done?'查看观察记录':'开始观察记录'}</small></button></article>`).join('')}</div>`;}
 const labList=[['greenhouse','Light Greenhouse','光照温室','plant'],['materials','Material Recovery Table','材料回收台','magnet'],['transport','Cargo Ramp','运输斜坡','ramp'],['sound','Sound Studio','音高工作室','sound'],['poles','Magnet Bench','磁极工作台','magnet'],['volume','Volume Studio','响度工作室','sound']];
 function benchHTML(){return `<h3>My Working Base<small>自由改变设置、比较记录、保存自己的解释</small></h3><p>These are simplified teaching models. Explore without a score or a required answer.<small>这些是简化教学模型；不计分，不要求唯一答案。运行记录与自己的预测、解释会保存在成长档案。</small></p><div class="learn-grid">${labList.map(([id,en,zh,a])=>`<article class="learn-card">${art({art:a})}<h3>${en}<small>${zh}</small></h3><p>${data().bench[id]?.seen.length||0} settings tested · 已测试设置</p><button class="primary" data-bench="${id}">Open workbench<small>进入工作台</small></button></article>`).join('')}</div>`;}
 function bindPanel(){const host=$('#learnPanel');host.querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>study(b.dataset.study));host.querySelectorAll('[data-family]').forEach(b=>b.onclick=()=>family(b.dataset.family));host.querySelectorAll('[data-bench]').forEach(b=>b.onclick=()=>bench(b.dataset.bench));host.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>open(b.dataset.panel));host.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});$('#learnFavorites')?.addEventListener('click',()=>{favOnly=!favOnly;render();});$('#learnPortfolio')?.addEventListener('click',portfolio);host.querySelectorAll('[data-word-audio]').forEach(b=>b.onclick=()=>speak('learn-r'+b.dataset.wordAudio+'-word'));bindStars(host,render);}
 function chrome(en,zh,body){
  ForcesLab.stop();if(narration.parentElement===dialog)document.body.append(narration);
  dialog.innerHTML=`<div class="lesson-header"><div><p class="eyebrow">GROW · SCIENCE ISLAND</p><h2>${esc(en)}<small class="title-zh">${esc(zh)}</small></h2></div><button id="learnClose" class="icon-btn" aria-label="Close and save / 关闭保存">✕</button></div><div class="final-body learn-body">${body}</div>`;
  $('#learnClose').onclick=()=>{save();dialog.close();render();};if(!dialog.open)dialog.showModal();if(!narration.hidden)mountNarration();
 }
 function draft(id){if(!data().drafts[id])data().drafts[id]={stage:id[0]==='s'?Math.min(data().levels[id]||0,2):0,variant:data().stats[id]?.variant||0,wrong:false,help:false,tokens:[],selected:null};return data().drafts[id];}
 function study(id){activeId=id;stopAudio();draft(id);save();drawStudy();dialog.scrollTop=0;}
 function drawStudy(){
  const id=activeId,c=find(id),d=draft(id),isSentence=id[0]==='s',q=isSentence?c:c.variants[d.variant];
  const stage=d.stage,opts=isSentence?(stage===0?c.options:c.gapoptions):q.options;
  const prompt=isSentence?(stage===0?'Listen. Which meaning fits?':stage===1?'Build the science sentence.':c.gap):q.en;
  const zh=isSentence?(stage===0?'听一听，选择符合的意思。':stage===1?c.zh:c.gapzh):q.zh;
  const bank=isSentence?[...c.parts.keys()].reverse():[];
  chrome(isSentence?'Science Sentence Lab':c.en,isSentence?'科学句子实验室':c.zh,`<p class="eyebrow">CHAPTER ${c.chapter} · ${isSentence?c.category:'NEW CONTEXT '+(d.variant+1)}</p>${isSentence?`<div class="learn-stages">${['Listen · 听懂','Build · 拼句','Transfer · 迁移'].map((s,i)=>`<button class="secondary ${i===stage?'selected':''}" data-stage="${i}" ${i>(data().levels[id]||0)?'disabled':''}>${i+1}. ${s}</button>`).join('')}</div>`:''}${art(c)}<h3>${esc(prompt)}</h3><details class="translation" id="studyTranslation"><summary>中文帮助</summary><p>${esc(zh)}</p></details><div class="listen-actions"><button class="listen" id="studyListen">▷ Listen<small>听英文</small></button><button class="text-button" id="studySlow">▷ Slower<small>慢速重听</small></button>${starButton(id)}</div>${isSentence&&stage===1?`<div class="sentence-result">${d.tokens.map((t,i)=>`<button class="sentence-piece" data-remove="${i}">${esc(c.parts[t])} ×</button>`).join('')||'<span>Tap the phrase blocks. · 点击短语块。</span>'}</div><div class="phrase-bank">${bank.map(i=>`<button class="chip" data-piece="${i}" ${d.tokens.includes(i)?'disabled':''}>${esc(c.parts[i])}</button>`).join('')}</div>`:`<div class="exam-options">${opts.map((o,i)=>`<button class="choice ${d.selected===i?'selected':''}" data-study-choice="${i}" aria-pressed="${d.selected===i}">${String.fromCharCode(65+i)} · ${esc(o)}</button>`).join('')}</div>`}<p id="studyFeedback" role="status" aria-live="polite"></p><div class="button-row"><button class="text-button" id="studyHint">Show a clue<small>查看线索</small></button><button class="primary" id="studyCheck">Check my answer<small>检查答案</small></button></div><p id="studyClue" hidden></p>${!isSentence?`<aside class="learn-word"><strong>${esc(c.word)}</strong><small>${esc(c.wordzh)}</small><button class="text-button" id="studyWord">▷ Listen · 听词</button>${starButton('w'+words.indexOf(c))}</aside>`:''}`);
  const audio=isSentence?'learn-'+id+(stage===2?'-gap':''):'learn-'+id+'-'+d.variant;
  $('#studyListen').onclick=()=>speak(audio);$('#studySlow').onclick=()=>speak(audio,.85);
  $('#studyTranslation').addEventListener('toggle',e=>{if(e.currentTarget.open){d.help=true;save();}});
  $('#studyWord')?.addEventListener('click',()=>speak('learn-'+id+'-word'));
  dialog.querySelectorAll('[data-study-choice]').forEach(b=>b.onclick=()=>{d.selected=+b.dataset.studyChoice;save();drawStudy();});
  dialog.querySelectorAll('[data-piece]').forEach(b=>b.onclick=()=>{d.tokens.push(+b.dataset.piece);save();drawStudy();});
  dialog.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{d.tokens.splice(+b.dataset.remove,1);save();drawStudy();});
  dialog.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{d.stage=+b.dataset.stage;d.tokens=[];d.selected=null;d.wrong=false;d.help=false;save();drawStudy();});
  $('#studyHint').onclick=()=>{d.help=true;save();$('#studyClue').hidden=false;$('#studyClue').textContent=isSentence?(stage===2?c.full:c.parts.join(' ')):q.fact+' '+q.factzh;};
  $('#studyCheck').onclick=()=>{
   const ready=isSentence&&stage===1?d.tokens.length===c.parts.length:d.selected!==null;
   if(!ready){$('#studyFeedback').textContent='Choose an answer or finish the sentence first. 请先选择答案或拼完句子。';return;}
   const ok=isSentence?(stage===1?d.tokens.every((n,i)=>n===i):d.selected===(stage===0?c.answer:c.gapanswer)):d.selected===q.answer;
   if(!ok){d.wrong=true;save();$('#studyFeedback').textContent='Try again. Listen or open a clue, then check the evidence. 再试试，可以重听或查看线索。';return;}
   const clean=!d.wrong,help=d.help,variant=d.variant;
   if(isSentence)data().levels[id]=Math.max(data().levels[id]||0,stage+1);
   complete(id,clean,help,stage,variant);result(id,stage,clean,help,variant);
  };bindStars(dialog,drawStudy);
 }
 function result(id,stage,clean,help,variant){const c=find(id),sentence=id[0]==='s',s=data().stats[id],q=sentence?null:c.variants[variant];
  chrome('A finding to keep','把发现留住',`<div class="learn-celebrate">✓ ${clean?'You used the evidence.':'You worked through the clue.'}<small>${clean?'你用证据完成了任务。':'你经过思考和提示完成了任务。'}</small></div><blockquote>${esc(sentence?(stage===2?c.full:c.parts.join(' ')):q.fact)}<small>${esc(sentence?(stage===2?c.fullzh:c.zh):q.factzh)}</small></blockquote><button class="listen" id="resultListen">▷ Listen to the explanation<small>听解释</small></button><p>Next revisit: ${s.due}<small>下次建议复习日期。今天重复练习不会反复延长间隔。</small></p><div class="share-card"><p>Explain this idea to your partner. Can you give another example?<small>向家人解释这个概念，还能举另一个例子吗？口头交流可选，不录音、不评分。</small></p></div><div class="button-row">${sentence&&stage<2?'<button class="primary" id="studyNextStage">Next stage<small>进入下一阶段</small> ↗</button>':''}<button class="secondary" id="studyNext">Back to my plan<small>返回今日计划</small></button><button class="secondary" id="studyWork">Try it in the base<small>去基地探索</small></button></div>`);
  $('#resultListen').onclick=()=>speak(sentence?'learn-'+id+(stage===2?'-full':''):'learn-'+id+'-'+variant+'-fact');
  $('#studyNextStage')?.addEventListener('click',()=>{const d=draft(id);d.stage=stage+1;save();study(id);});
  $('#studyNext').onclick=()=>{dialog.close();open('plan');};$('#studyWork').onclick=()=>{dialog.close();open('bench');};dialog.scrollTop=0;
 }
 function labSpec(id){
  if(id==='greenhouse')return {type:'experiment',kind:'shoot',trials:[{id:'0',en:'Lamp on the left',zh:'灯在左边',light:'left',result:'Over time, the young shoot may bend left toward the lamp.',resultzh:'经过一段时间，幼茎可能朝左侧灯光弯曲。'},{id:'1',en:'Lamp on the right',zh:'灯在右边',light:'right',result:'Over time, the young shoot may bend right toward the lamp.',resultzh:'经过一段时间，幼茎可能朝右侧灯光弯曲。'}]};
  return CH7.missions[{materials:10,transport:0,sound:16,poles:11,volume:17}[id]].steps[0];
 }
 function bench(id){activeLab=id;stopAudio();const b=data().bench[id]||(data().bench[id]={seen:[],order:[],prediction:'',note:''});save();const spec=labSpec(id),label=labList.find(l=>l[0]===id);
  chrome(label[1],label[2],`<p>Predict, change a setting, and compare the records.<small>先预测，再改变设置并比较记录。模型结果代表指定条件，不是实物测量。</small></p><label class="learn-label">My prediction · 我的预测<textarea id="benchPrediction" maxlength="1200" placeholder="What might happen? / 可能发生什么？">${esc(b.prediction)}</textarea></label><button class="listen" id="benchIntro">▷ Listen to the task<small>听任务</small></button>${ForcesLab.html(spec,b)}<label class="learn-label">My explanation · 我的解释<textarea id="benchNote" maxlength="1200" placeholder="What changed? What stayed the same? / 什么变了，什么没变？">${esc(b.note)}</textarea></label><p id="benchSaved" role="status">Notes save as you type. · 输入即保存。</p><button class="secondary" id="benchPortfolio">See my portfolio<small>查看成长档案</small></button>`);
  for(const [el,key] of [['benchPrediction','prediction'],['benchNote','note']])$('#'+el).oninput=e=>{b[key]=e.target.value;save();$('#benchSaved').textContent=storageOK?'Saved on this device · 已存本机':'Not saved — export a backup · 保存失败，请导出备份';};
  const mid={materials:'g11',transport:'g1',sound:'g17',poles:'g12',volume:'g18'}[id];
  $('#benchIntro').onclick=()=>speak(mid?mid+'-intro':'learn-greenhouse');
  ForcesLab.bind(dialog,spec,b,tid=>{b.seen=[...new Set([...b.seen,tid])];b.order=[...b.order.filter(x=>x!==tid),tid];save();bench(id);},tid=>speak(mid?mid+'-trial'+tid:'learn-greenhouse-trial'+tid));
  $('#benchPortfolio').onclick=portfolio;
 }
 function family(id){stopAudio();const f=LEARN.family.find(f=>f.id===id),r=data().family[id]||(data().family[id]={observation:'',evidence:'',explanation:'',parent:'',done:null});save();
  chrome(f.en,f.zh,`${art(f)}<p>${esc(f.enprompt)}<small>${esc(f.zhprompt)}</small></p><button class="listen" id="familyListen">▷ Listen<small>听实地任务</small></button><p>${esc(f.question)}<small>${esc(f.questionzh)}</small></p>${[['observation','What I observed','我的观察'],['evidence','My evidence / measurement','依据或测量记录'],['explanation','My explanation or next question','我的解释或下一问题'],['parent','Family note (optional)','亲子交流备注（可选）']].map(([key,en,zh])=>`<label class="learn-label">${en}<small>${zh}</small><textarea data-family-note="${key}" maxlength="1200">${esc(r[key])}</textarea></label>`).join('')}<p id="familyStatus" role="status">${r.done?'✓ Field note completed · 记录完成于 '+r.done:'Draft saves as you type · 输入即保存草稿'}</p><p class="learn-muted">This is your own field record, not an automatically graded answer.<small>这是自己的实地观察记录，不自动判断科学结论对错。</small></p><div class="button-row"><button class="primary" id="familyDone">Save completed field note<small>完成本次记录</small></button><button class="secondary" id="familyPortfolio">My portfolio<small>查看成长档案</small></button></div>`);
  $('#familyListen').onclick=()=>speak('learn-'+id);
  dialog.querySelectorAll('[data-family-note]').forEach(el=>el.oninput=()=>{r[el.dataset.familyNote]=el.value;if(!r.observation.trim()||!r.explanation.trim())r.done=null;save();$('#familyStatus').textContent=storageOK?'Saved on this device · 已存本机':'Not saved — export a backup · 保存失败，请导出备份';});
  $('#familyDone').onclick=()=>{if(!r.observation.trim()||!r.explanation.trim()){$('#familyStatus').textContent='Add an observation and an explanation or next question first. 请先写观察，以及解释或下一问题。';return;}r.done=today();save();$('#familyStatus').textContent='✓ Field note complete. It is in your portfolio. 已完成，已收进成长档案。';render();};$('#familyPortfolio').onclick=portfolio;
 }
 function portfolioOverview(){return `<h3>My Science Portfolio<small>把学习变成一本自己的研究册</small></h3><p>Your chapter findings, practice progress, experiments, and family observations stay together.<small>汇集章节成果、复习进展、自由实验和亲子观察。支持打印或下载独立HTML研究册。</small></p><button class="primary" id="learnPortfolio">Open & print my portfolio<small>打开并打印成长档案</small></button><h3>My word collection<small>收藏的科学词汇</small></h3><div class="learn-grid compact">${words.map((w,i)=>({w,i})).filter(({i})=>data().favorites.includes('w'+i)).map(({w,i})=>`<article class="learn-card"><h4>${esc(w.word)}<small>${esc(w.wordzh)}</small></h4><button class="listen" data-word-audio="${i}">▷ Listen · 听词</button>${starButton('w'+i)}</article>`).join('')||'<p>Save a word from a review activity with ☆.<small>在概念复习中点星号收藏词汇。</small></p>'}</div><h3>My saved ideas<small>收藏的概念与句子</small></h3><div class="learn-grid compact">${data().favorites.filter(id=>id[0]!=='w').map(id=>{const c=find(id);return `<article class="learn-card"><p>${esc(title(c))}<small>${esc(c.zh)}</small></p><button class="secondary" data-study="${id}">Revisit · 重温</button>${starButton(id)}</article>`;}).join('')||'<p>No saved ideas yet. · 还没有收藏的概念或句子。</p>'}</div>`;}
 function portfolioContent(){
  const p=profile(),d=data(),last=p.final.attempts.at(-1),sc=last?FinalChallenge.score(last):null;
  const chapters=[{en:'Plant Life Cycles',done:p.completed,total:6,missions:levels},...[[CH2,'animals'],[CH3,'earth'],[CH4,'fossils'],[CH5,'resources'],[CH6,'motion'],[CH7,'forces'],[REVIEW,'expedition']].map(([mod,key],i)=>({en:i<6?FINAL.chapters[i+1]:'Great Island Expedition',done:p[key].completed,total:mod.missions.length,missions:mod.missions}))];
  return `<article class="portfolio-print"><header><p>GOLDEN FROG SCIENCE ISLAND</p><h1>My Grade 2 Science Portfolio</h1><h2>我的科学研究册</h2><p>${state.active==='child'?'Young explorer · 小探险家':'Adult researcher · 成人研究员'} · ${today()}</p></header><h2>My chapter discoveries · 章节发现</h2>${chapters.map(c=>`<section><h3>${esc(c.en)} · ${c.done.length}/${c.total}</h3><p>${c.done.map(i=>esc(c.missions[i]?.en)).join(' · ')||'Ready to begin · 等待探索'}</p></section>`).join('')}<h2>My final challenge · 全册挑战</h2>${sc?`<p>Science ${sc.science}/21 · English ${sc.english}/7</p><p>Latest completed assessment · 最近一次已完成考核</p>${sc.rows.map((r,i)=>`<p>${esc(FINAL.chapters[i])}: ${r.science}/3 science · ${r.english}/1 English</p>`).join('')}`:'<p>No completed assessment yet. · 暂无完整考核记录。</p>'}<h2>Practice over time · 练习中的进步</h2>${Object.entries(d.stats).map(([id,s])=>`<section><h3>${esc(title(find(id)))}</h3><p>First submitted response: ${s.first?'correct':'needed another try'} · Latest practice: ${s.lastOk?'correct first try':'worked through a retry'}<br>首次作答${s.first?'正确':'需再尝试'} · 最近${s.lastOk?'首次答对':'经过重试完成'} · ${s.runs} practice days · 下次 ${s.due}</p></section>`).join('')||'<p>Start a daily plan to build your record. · 完成每日练习后会留下记录。</p>'}<h2>My science sentences · 科学句子</h2>${sentences.filter(s=>d.levels[s.id]).map(s=>`<blockquote>${esc(s.parts.join(' '))}<p>${esc(s.zh)} · ${d.levels[s.id]}/3 stages</p></blockquote>`).join('')||'<p>No sentence stages completed yet. · 还没有完成的句子阶段。</p>'}<h2>My workbench records · 自由实验</h2>${labList.filter(([id])=>d.bench[id]).map(([id,en,zh])=>{const b=d.bench[id];return `<section><h3>${en} · ${zh}</h3><p>Prediction · 预测：${esc(b.prediction||'Not recorded · 未填写')}</p>${b.order.map(tid=>{const t=labSpec(id).trials.find(t=>t.id===tid);return `<p>${esc(t.en)}: ${esc(t.result)}<br>${esc(t.resultzh)}</p>`;}).join('')}<p>My explanation · 我的解释：${esc(b.note||'Not recorded · 未填写')}</p></section>`;}).join('')||'<p>No experiments recorded yet. · 还没有自由实验记录。</p>'}<h2>Family field notes · 亲子观察</h2>${LEARN.family.filter(f=>d.family[f.id]).map(f=>{const r=d.family[f.id];return `<section><h3>${esc(f.en)} · ${esc(f.zh)}</h3><p>${r.done?'Completed · '+r.done:'Draft · 草稿'}</p>${[['observation','Observation · 观察'],['evidence','Evidence · 依据'],['explanation','Explanation / question · 解释或问题'],['parent','Family note · 亲子备注']].map(([k,label])=>`<p><strong>${label}</strong><br>${esc(r[k]||'—')}</p>`).join('')}</section>`;}).join('')||'<p>No field notes yet. · 暂无亲子观察。</p>'}<footer>Original companion activities · Personal learning record. Family notes are self-reported.<br>原创伴学活动 · 个人学习记录 · 亲子观察为自行填写，未自动核验。</footer></article>`;
 }
 function portfolio(){stopAudio();chrome('My Science Portfolio','我的科学成长档案',`<div class="button-row no-print"><button class="primary" id="portfolioPrint">Print / save as PDF<small>打印或存为PDF</small></button><button class="secondary" id="portfolioDownload">Download research book<small>下载独立HTML研究册</small></button></div>${portfolioContent()}`);
  $('#portfolioPrint').onclick=()=>window.print();$('#portfolioDownload').onclick=()=>{const html='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Science Portfolio</title><style>body{max-width:900px;margin:40px auto;padding:20px;font:16px/1.7 system-ui;color:#284e3a}h1,h2{color:#345d45}section,blockquote{padding:15px;border:1px solid #d9dfcc;margin:18px 0;break-inside:avoid}p{white-space:pre-wrap}footer{font-size:12px}</style>'+portfolioContent()+'</html>';const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='my-grade2-science-portfolio.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);};dialog.scrollTop=0;
 }
 function addNext(host,ch){if(host.querySelector('.learn-next'))return;const b=document.createElement('button');b.className='secondary learn-next';b.innerHTML='Keep this idea growing <small>把这个概念用英语再练一次</small> ↗';b.onclick=()=>{host.close();study(sentences.find(c=>c.chapter===Math.min(ch,7)).id);};host.append(b);}
 render();if(new URLSearchParams(location.search).get('learn'))open(tabs.some(t=>t[0]===new URLSearchParams(location.search).get('learn'))?new URLSearchParams(location.search).get('learn'):'plan');
 return {render,open,study,bench,family,portfolio,plan,today,later,addNext};
})();
